import re
from typing import Tuple, List, Optional

def evaluate(expr: str) -> float:
    if not expr:
        raise ValueError("empty string")

    # Tokenize the expression
    tokens = tokenize(expr)
    if not tokens:
        raise ValueError("malformed input")

    # Parse the expression into an abstract syntax tree (AST)
    ast = parse(tokens)
    if not ast:
        raise ValueError("malformed input")

    # Evaluate the AST
    return evaluate_ast(ast)

def tokenize(expr: str) -> List[str]:
    # Match numbers, operators, and parentheses
    token_pattern = r'(\d+\.?\d*|\+|\-|\*|/|\(|\))'
    tokens = re.findall(token_pattern, expr)

    # Handle unary minus
    i = 0
    while i < len(tokens):
        if tokens[i] == '-' and (i == 0 or tokens[i-1] in '()'):
            tokens[i] = 'UNARY-'
        i += 1

    return tokens

def parse(tokens: List[str]) -> Optional[Tuple[str, List]]:
    # Parse expressions with precedence
    return parse_expression(tokens)

def parse_expression(tokens: List[str]) -> Optional[Tuple[str, List]]:
    left = parse_term(tokens)
    if not left:
        return None
    while tokens and tokens[0] in ('+', '-'):
        op = tokens.pop(0)
        right = parse_term(tokens)
        if not right:
            return None
        left = ('BINOP', op, left, right)
    return left

def parse_term(tokens: List[str]) -> Optional[Tuple[str, List]]:
    left = parse_factor(tokens)
    if not left:
        return None
    while tokens and tokens[0] in ('*', '/'):
        op = tokens.pop(0)
        right = parse_factor(tokens)
        if not right:
            return None
        left = ('BINOP', op, left, right)
    return left

def parse_factor(tokens: List[str]) -> Optional[Tuple[str, List]]:
    if not tokens:
        return None
    token = tokens[0]
    if token == '(':
        tokens.pop(0)
        expr = parse_expression(tokens)
        if not expr or tokens[0] != ')':
            return None
        tokens.pop(0)
        return expr
    elif token == 'UNARY-':
        tokens.pop(0)
        right = parse_factor(tokens)
        if not right:
            return None
        return ('UNARY-', right)
    elif re.fullmatch(r'\d+\.?\d*', token):
        tokens.pop(0)
        return ('NUMBER', float(token))
    else:
        return None

def evaluate_ast(node: Tuple[str, List]) -> float:
    if node[0] == 'NUMBER':
        return node[1]
    elif node[0] == 'UNARY-':
        return -evaluate_ast(node[1])
    elif node[0] == 'BINOP':
        left = evaluate_ast(node[2])
        right = evaluate_ast(node[3])
        op = node[1]
        if op == '+':
            return left + right
        elif op == '-':
            return left - right
        elif op == '*':
            return left * right
        elif op == '/':
            if right == 0:
                raise ZeroDivisionError("division by zero")
            return left / right
        else:
            raise ValueError("malformed input")
    else:
        raise ValueError("malformed input")
