from collections import defaultdict, deque

def topo_order(deps: dict[str, list[str]]) -> list[str]:
    # Build in-degree map and adjacency list
    in_degree = defaultdict(int)
    graph = defaultdict(list)

    for task, prereqs in deps.items():
        for prereq in prereqs:
            graph[prereq].append(task)
            in_degree[task] += 1
        if task not in in_degree:
            in_degree[task] = 0

    # Initialize queue with tasks having zero in-degree
    queue = deque(sorted([task for task in in_degree if in_degree[task] == 0]))

    result = []

    while queue:
        task = queue.popleft()
        result.append(task)

        for neighbor in graph[task]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != len(deps):
        raise ValueError("Cycle detected in dependencies")

    return result
