from typing import Dict, List, Optional

class ChatServer:
    def __init__(self, host: str = "127.0.0.1", port: int = 0):
        self.host = host
        self.port = port
        self.server_socket = None
        self.clients: Dict[str, socket.socket] = {}
        self.lock = threading.Lock()

    def start(self) -> int:
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.bind((self.host, self.port))
        self.server_socket.listen(5)
        self.port = self.server_socket.getsockname()[1]
        print(f"Server started on port {self.port}")

        for _ in range(5):
            try:
                client_socket, addr = self.server_socket.accept()
                threading.Thread(target=self.handle_client, args=(client_socket,)).start()
            except socket.error:
                break

        return self.port

    def stop(self):
        if self.server_socket:
            self.server.got_close = True
            self.server_socket.close()
            for client in self.clients.values():
                client.close()
            self.clients.clear()

    def handle_client(self, client_socket: socket.socket):
        with self.lock:
            name = self.get_name(client_socket)
            if not name:
                return
            self.clients[name] = client_socket
            self.broadcast(f"* {name} joined\n", exclude=name)

        try:
            while True:
                line = client_socket.recv(1024).decode('utf-8')
                if not line:
                    break
                if line.startswith("NAME "):
                    self.handle_name(client_socket, line)
                else:
                    self.broadcast(f"{name}: {line}\n", exclude=name)
        except Exception as e:
            print(f"Error handling client: {e}")
        finally:
            with self.lock:
                if name in self.clients:
                    del self.clients[name]
                    self.broadcast(f"* {name} left\n", exclude=name)
                    client_socket.close()

    def get_name(self, client_socket: socket.socket) -> Optional[str]:
        line = client_socket.recv(1024).decode('utf-8')
        if not line:
            return None
        if line.startswith("NAME "):
            name = line.split(" ", 1)[1].strip()
            if name in self.clients:
                client_socket.send("ERROR name taken\n".encode('utf-8'))
                client_socket.close()
                return None
            client_socket.send("OK\n".encode('utf-8'))
            return name
        return None

    def handle_name(self, client_socket: socket.socket, line: str):
        name = line.split(" ", 1)[1].strip()
        if name in self.clients:
            client_socket.send("ERROR name taken\n".encode('utf-8'))
            client_socket.close()
        else:
            client_socket.send("OK\n".encode('utf-8'))

    def broadcast(self, message: str, exclude: Optional[str] = None):
        with self.lock:
            for name, client in self.clients.items():
                if name != exclude:
                    try:
                        client.send(message.encode('utf-8'))
                    except socket.error:
                        pass
