import threading

class SafeCounter:
    def __init__(self):
        self._value = 0
        self._lock = threading.Lock()

    @property
    def value(self):
        with self._lock:
            return self._value

    def increment(self):
        with self._lock:
            self._value += 1

def count_with_threads(n_threads: int, increments: int) -> int:
    counter = SafeCounter()
    threads = []

    def worker():
        for _ in range(increments):
            counter.increment()

    for _ in range(n_threads):
        t = threading.Thread(target=worker)
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    return counter.value
