class NotFound(Exception):
    pass


class MethodNotAllowed(Exception):
    pass


class Router:
    def __init__(self):
        self.routes = {}

    def add(self, method, pattern, handler):
        if method not in self.routes:
            self.routes[method] = []
        self.routes[method].append((pattern, handler))

    def dispatch(self, method, path):
        path = path.rstrip('/')
        segments = path.split('/')

        if method not in self.routes:
            raise NotFound()

        for pattern, handler in self.routes[method]:
            pattern_segments = pattern.split('/')
            if len(pattern_segments) != len(segments):
                continue

            params = {}
            match = True
            for p_seg, seg in zip(pattern_segments, segments):
                if p_seg.startswith('{') and p_seg.endswith('}'):
                    name = p_seg[1:-1]
                    if not name:
                        continue
                    if seg == '':
                        match = False
                        break
                    params[name] = seg
                elif p_seg != seg:
                    match = False
                    break

            if match:
                return handler, params

        raise NotFound()
