from typing import Dict, List

def dict_diff(old: Dict, new: Dict) -> List[str]:
    def compare_dicts(old_dict: Dict, new_dict: Dict, path: str = "") -> List[str]:
        diff = []
        all_keys = set(old_dict.keys()).union(set(new_dict.keys()))
        for key in sorted(all_keys):
            full_path = f"{path}.{key}" if path else key
            if key in old_dict and key in new_dict:
                if isinstance(old_dict[key], dict) and isinstance(new_dict[key], dict):
                    sub_diff = compare_dicts(old_dict[key], new_dict[key], full_path)
                    diff.extend(sub_diff)
                else:
                    if old_dict[key] != new_dict[key]:
                        diff.append(f"changed: {full_path}")
            elif key in old_dict:
                diff.append(f"removed: {full_path}")
            else:
                diff.append(f"added: {full_path}")
        return diff

