def to_roman(n: int) -> str:
    if not 1 <= n <= 3999:
        raise ValueError("Input must be in range 1..3999")
    roman_numerals = [
        ("M", 1000), ("CM", 900), ("D", 500), ("CD", 400),
        ("C", 100), ("XC", 90), ("L", 50), ("XL", 40),
        ("X", 10), ("IX", 9), ("V", 5), ("IV", 4), ("I", 1)
    ]
    result = ""
    for symbol, value in roman_numerals:
        while n >= value:
            result += symbol
            n -= value
    return result


def from_roman(s: str) -> int:
    if not s.isupper() or not s.replace("IV", "").replace("IX", "").replace("XL", "").replace("XC", "").replace("CD", "").replace("CM", "").isalnum():
        raise ValueError("Input must be uppercase Roman numerals in canonical form")
    if not s:
        raise ValueError("Input cannot be empty")
    roman_numerals = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0
    prev_value = 0
    for char in reversed(s):
        value = roman_numerals[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total
